INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1452, 339, 'запустить систему в режиме отладки, далее выставить точку останова, запустить замер производительности', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1453, 339, 'запустить систему в режиме отладки, запустить замер производительности', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1454, 339, 'запустить систему в режиме "Конфигуратор", запустить замер производительности', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1455, 339, 'запустить систему в режиме "Конфигуратор", запустить замер производительности, запустить систему в режиме отладки или подключиться к системе для отладки', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1456, 339, 'Варианты 1, или 2, или 4', true);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1457, 339, 'Верны все варианты', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1458, 340, 'Нет, время исполнения вызываемой функции всегда будет входить в замер производительности', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1459, 340, 'Это делается по умолчанию, поскольку в замер производительности всегда входит время исполнения строк самой процедуры, без учета времени вызываемых из нее процедур и функций', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1460, 340, 'Можно включить или выключить время выполнения вызываемых процедур и функций перед началом замера производительности', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1461, 340, 'Можно включить или выключить время выполнения вызываемых процедур и функций уже в отчете замера производительности', true);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1468, 342, 'для определения сколько раз вызывалась данная строка кода при исполнении модуля', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1469, 342, 'для определения сколько раз вызывалась текущая процедура или функция в процессе исполнения модуля', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1470, 342, 'для определения - какие процедуры и функции данного модуля и сколько раз вызывались', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1471, 342, 'для определения - какие процедуры и функции вызывались, прежде чем управление перешло на строку кода, которая исполняется в текущий момент', true);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1472, 343, 'Нельзя, поскольку окно «Выражение» дает возможность увидеть только состав и название колонок таблицы значений,', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1473, 343, 'Нельзя, но зато можно увидеть данные построчно в цикле перебора строк таблицы значений или при помощи прямого позиционирования на строках по индексам', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1474, 343, 'Можно, поскольку содержимое таблицы значений будет сразу же видно в окне «Результат»', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1475, 343, 'Можно, но только посредством команды «Показать в отдельном окне»,', true);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1476, 343, 'Варианты 1 и 2', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1477, 344, 'можно увидеть значения переменных', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1478, 344, 'можно и сами значения переменных, и значения свойств этих переменных, если переменные — агрегатного типа', true);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1479, 344, 'можно увидеть номер исполняемой строки кода, название модуля и объекта', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1480, 344, 'Варианты 1 и 3', false);
