INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1482, 345, 'используется для выхода из конфигуратора в процессе отладки', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1483, 345, 'используется для выхода из исполняемого процесса отладки', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1484, 345, 'используется для выхода из пошаговой трассировки функции или процедуры, и останова на следующей после ее вызова строке кода', true);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1485, 346, 'для прекращения процесса отладки. Причем сеанс работы в режиме "1С:Предприятие" будет закрыт', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1486, 346, 'для прекращения процесса отладки. Причем сеанс работы в режиме "1С:Предприятие" не будет закрыт', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1844, 428, 'Модуль менеджера', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1487, 346, 'для прекращения процесса отладки. Причем будет закрыт и сеанс работы в режиме "1С:Предприятие", и в режиме "1С:Предприятие"', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1488, 346, 'для останова процесса исполнения кода, и дальнейшего пошагового исполнения его, начиная с исполняемой на момент останова строки', true);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1489, 347, 'Нет, но можно последовательно обойти все точки останова в открытом модуле', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1490, 347, 'По всем — нет, но можно получить посредством специального пункта меню «Отладка» список всех точек останова текущего модуля', false);
