INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1493, 348, 'предназначена для организации останова на условных операторах', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1494, 348, 'предназначена для останова на строке кода, но только в случае истинности выполнения условия, заданного при установке данной точки останова', true);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1495, 348, 'предназначена для останова на строке кода, но только в случае если результат условия, заданного при установке данной точки останова, - Ложь.', false);
