INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1499, 349, 'Можно. В ряде случаев нельзя лишь обновить конфигурацию базы данных', true);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1500, 350, 'должна быть завершена работа в режиме «1С:Предприятие» для всех пользователей данной конфигурации, обновлена конфигурация базы данных и повторно запущена отладка', true);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1501, 350, 'должна быть завершена работа в режиме «1С:Предприятие» только для собственного процесса (остальные пользователи могут продолжать работать), обновлена конфигурация базы данных и повторно запущена отладка', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1502, 350, 'ничего специально делать не нужно — изменения автоматически вносятся в конфигурацию базы данных и учитываются на последующих шагах трассировки', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1503, 351, 'возможно в любом случае', false);
