INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1506, 351, 'возможно только в том случае, если к информационной базе подключен максимум один сеанс «1С:Предприятие» (запущенный в режиме отладки), или изменения не связаны с изменениями структуры таблиц информационной базы', true);
