INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1509, 352, 'этот сеанс можно не закрывать, но необходимо запустить конфигурацию в режиме "Конфигуратор", а в нем через меню "Отладка" - "Начать отладку"', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (1510, 352, 'этот сеанс можно не закрывать, но необходимо запустить конфигурацию в режиме "Конфигуратор", а в нем подключиться к предмету отладки', true);
