INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (2456, 581, 'прежде, чем рассчитать зависимую от базы запись, нужно рассчитать запись, попадающую в эту базу. В процессе проведения документа будет произведена одна процедура записи в регистр расчета', false);
