INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (2921, 697, 'Не хранятся', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (2922, 697, 'Хранятся. Они не ограничены периодом рассчитанных итогов, так как рассчитываются системой автоматически при открытии следующего периода', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (2923, 697, 'Могут храниться, но ограничены периодом рассчитанных итогов. Если их не рассчитали, то и не хранятся. Управлять рассчитанными итогами можно в режиме 1С:Предприятие', true);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (2924, 697, 'Верны ответы 2 и 3, так как автоматический расчет промежуточных итогов может быть задан в режиме конфигуратора', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (2925, 698, 'Регистр накопления с видом «Обороты» позволяет получить информацию об оборотах за период эффективнее, чем регистр с видом «Остатки»', true);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (2926, 698, 'Регистр накопления с видом «Обороты» позволяет получить информацию об оборотах за период с такой же эффективностью, что и регистр с видом «Остатки», но при проведении документа запись в регистр будет происходить быстрее, т.к. не будет происходить расчет остатков', false);
INSERT INTO public.answers (id, question_id, text, is_correct) VALUES (2927, 698, 'Регистр накопления с видом «Обороты» повышает общую эффективность работы базы, т.к. информация об остатках не хранится, не пересчитывается, и, следовательно, уменьшается размер базы', false);
